import app from './app';
import ajax from '@/utils/ajax';
import { Message } from "@arco-design/web-react";
import userStore from './userStore';
import { PluginExtraInfo, pluginExtrainfoDefaultValue, PluginInfo } from '@/types/plugin';
import { action, observable, makeObservable } from 'mobx';
import user from "@code/store/user";
import language from './language';
import _ from 'lodash';


class Store {
    @observable extraInfo: PluginExtraInfo = _.cloneDeep(pluginExtrainfoDefaultValue);

    @action assignExtraInfo = (data: Partial<PluginExtraInfo>) => {
        this.extraInfo = { ...this.extraInfo, ...data };
    }


    /**
     * @保存插件信息
     */
    savaExtraInfo = () => {
        return ajax.post('/apijson/put', {
            Plugins: {
                id: this.info.id,
                extraInfo: this.extraInfo,
            }
        })
    }

    /**
     * 插件信息
     */
    @observable info:PluginInfo = {
        extraInfo: {
            datasheets: []
        }
    };


    @action setInfo = (data) => {
        this.info = data;
        this.assignExtraInfo(data.extraInfo || {})
    }


    // 获取用户信息
    getPluginInfo = (id: string) => {
        app.appId = id;
        app.tenantId = id;
        return ajax.post('/dev/getPluginInfo', {
            pluginId: id
        }).then((res) => {
            if(!res.info){
                Message.success("当前插件不存在，或没有权限");
                throw `${id} 插件获取失败`
            }
            this.setInfo(res.info);
            userStore.setDevToken(res.token);
            return Promise.all([
                // 加载当前项目多语言环境
                language.reloadPlugin(),
            ])
        })
    }

    constructor() {
        makeObservable(this);
    }
}

export default new Store();